    last_security_update timestamp with time zone,
    active_users integer DEFAULT 0,
    api_calls integer DEFAULT 0,
    feature_usage jsonb DEFAULT '{}'::jsonb,
    user_engagement numeric(5,2) DEFAULT 0,
