    CONSTRAINT valid_platform_frequency CHECK (((frequency)::text = ANY ((ARRAY['immediate'::character varying, 'digest_hourly'::character varying, 'digest_daily'::character varying, 'digest_weekly'::character varying])::text[])))
);


