        ADD CONSTRAINT external_connections_tenant_source_endpoint_fkey FOREIGN KEY (tenant_id, source_endpoint_id) REFERENCES public.asset_endpoints(tenant_id, id) ON DELETE SET NULL (source_endpoint_id);
  END IF;
